# Code generated by Claude
"""
Tests of the drop monitor (src/mpvi_monitors.py, D7) and of the oracle's place check with a two-condition criterion (design plan 8 D4 addendum 6), on the real task model and hand-set states.
No simulation run, no rendering, no API call: the model is loaded, joint values are set, and the oracle or the monitor is read.

    python experiments/mpvi_monitor_test.py

Drop monitor (fake observations, the real finger joint index; a stand-in oracle gives the "held?" verdict, its answer is only logged):
  1. a held grasp that stays at its width logs nothing;
  2. a forced slip (the fingers close further than the held width allows, for longer than the dwell) logs ONE "dropped" entry with the time, the finger opening, the width held and the oracle's "held?"
     verdict of that tick, whichever way the oracle answers (a drop while the oracle still says held is a disagreement to be measured, not hidden); an in-sim forced slip is NOT tested here;
  3. a blip shorter than the dwell logs nothing; closing the fingers after the open event logs nothing; a missing signal is a logged monitor_error, never an exception;
  4. the monitor uses only the finger opening and the events (the log entry carries no object pose).
Oracle, place with two conditions (the real oracle on the real model, the beaker teleported onto the hotplate or not, the fingers set open or closed): only the plate holds -> FAIL naming the gripper;
only the open gripper holds -> FAIL naming the plate; both -> PASS.
"""

import sys
from pathlib import Path

import mujoco

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.mpvi_modules import make_oracle_checker  # noqa: E402
from src.mpvi_monitors import make_drop_monitor  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import bench_top_z, load_task  # noqa: E402
from src.task_config import PICK_PLACE_CFG, SUCCESS_CFG, TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    sim = load_task(cameras=False)
    model, data = sim.model, sim.data
    fq = int(model.jnt_qposadr[arm_ids(model, "left")["finger_jnt"][0]])
    cfg = PICK_PLACE_CFG
    dt = 1 / 30

    print("1-4. the drop monitor")
    held = {"passed": True, "reason": ""}
    orc = {"name": "fake", "check": lambda seg, ev, obs, decides=False: dict(held, details={})}
    seg = {"type": "manipulation", "primitive": "pick", "description": "Grasp the beaker"}

    def obs_at(t, travel):
        q = np.zeros(model.nq)
        q[fq] = travel
        return {"time": t, "joint_angles": q}

    def run(profile, events_at=None, oracle_passed=True):
        held.update(passed=oracle_passed, reason="" if oracle_passed else "not held")
        m = make_drop_monitor(model, orc, "left")
        out = []
        for k, travel in enumerate(profile):
            ev = [(e, seg) for kk, e in (events_at or {}).items() if kk == k]
            out += m["tick"](obs_at(k * dt, travel), ev, seg)
        return out, m

    width = 0.020
    out, _ = run([width] * 60 + [width - 0.001] * 30, {0: "gripper_closed"})
    check("a grasp that stays at its width (1 mm of noise) logs nothing", out == [])
    slip = [width] * 20 + [width - 0.010] * 40
    out, m = run(slip, {0: "gripper_closed"}, oracle_passed=False)
    e = out[0] if out else {}
    check("a forced slip logs ONE 'dropped' entry with the time, the finger opening, the width held and the oracle's held? verdict (here: not held)", len(out) == 1 and e["kind"] == "dropped"
          and abs(e["finger_opening_m"] - (width - 0.010)) < 1e-9 and abs(e["held_width_m"] - width) < 1e-9 and e["oracle_held"] is False and abs(e["time"] - (20 * dt + cfg["drop_dwell_s"])) < 2 * dt, f"{e}")
    out2, _ = run(slip, {0: "gripper_closed"}, oracle_passed=True)
    check("with the oracle still saying held the entry says so (a disagreement to measure)", len(out2) == 1 and out2[0]["oracle_held"] is True)
    check("the entry has no object pose: only time, opening, width and the oracle's verdict", set(e) == {"kind", "time", "below_since", "finger_opening_m", "held_width_m", "oracle_held", "oracle_reason"}, f"{sorted(e)}")
    out, _ = run([width] * 20 + [width - 0.010] + [width] * 40, {0: "gripper_closed"})
    check("a blip shorter than the dwell logs nothing", out == [])
    out, _ = run([width] * 10 + [0.044] * 5 + [0.0] * 30, {0: "gripper_closed", 10: "gripper_opened"})
    check("after the open event, closing the fingers logs nothing", out == [])
    out, _ = run([0.0] * 30)
    check("before any close event the monitor is not armed", out == [])
    m = make_drop_monitor(model, orc, "left")
    new = m["tick"]({"time": 0.0}, [("gripper_closed", seg)], seg)
    check("a missing signal is a logged monitor_error, never an exception", len(new) == 1 and new[0]["kind"] == "monitor_error", f"{new}")

    print("\nthe oracle's place check with a two-condition criterion")
    top_site = data.site("hotplate_top").xpos.copy()
    jq = model.joint("task_beaker_free").qposadr[0]
    oracle = make_oracle_checker(model, data, None, None, "left", TASK_CFG, SUCCESS_CFG)
    place_seg = {"type": "manipulation", "primitive": "place", "description": "Place the beaker on the hotplate"}
    top = bench_top_z(model)

    def state(on_plate, open_gripper):
        xyz = [top_site[0], top_site[1], top_site[2] + 0.002] if on_plate else [*TASK_CFG["beaker_xy"], top + 0.002]
        data.qpos[jq:jq + 3] = xyz
        data.qpos[jq + 3:jq + 7] = [1, 0, 0, 0]
        data.qpos[fq] = TASK_CFG.get("finger_open", 0.044) if open_gripper else 0.02
        mujoco.mj_forward(model, data)
        return oracle["check"](place_seg, "gripper_opened", {})
    v = state(on_plate=True, open_gripper=False)
    check("only the plate condition holds (the gripper is still closed): FAIL, the reason names the gripper and not the plate", not v["passed"] and "gripper is not open" in v["reason"]
          and "not standing on the hotplate" not in v["reason"], v["reason"][:100])
    v = state(on_plate=False, open_gripper=True)
    check("only the open gripper holds (the beaker is not on the plate): FAIL, the reason names the plate and not the gripper", not v["passed"] and "not standing on the hotplate" in v["reason"]
          and "gripper is not open" not in v["reason"], v["reason"][:100])
    v = state(on_plate=True, open_gripper=True)
    check("both conditions hold: PASS", v["passed"] and v["reason"] == "", v["reason"][:100])
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
